 const roles={
  'background':'semantic.surface.default','body':'semantic.text.body','secondary':'semantic.text.secondary','border':'semantic.border.default','font':'font.size.13','line':'font.line.20','width':'component.response.width',
  'bubble.background':'semantic.action.primary','bubble.foreground':'semantic.text.inverse','bubble.radius':'radius.9','bubble.paddingX':'space.12','bubble.paddingY':'space.6','bubble.gap':'space.28',
  'history.width':'size.320','history.radius':'radius.lg','history.rowHeight':'size.34','history.resultsHeight':'size.212','history.shadow':'shadow.menu',
  'transcript.top':'space.40','transcript.inset':'space.32','transcript.gap':'space.36','transcript.height':'size.640','transcript.pendingHeight':'size.220',
  'panel.width':'size.391','panel.radius':'radius.3xl','panel.headerHeight':'size.56','panel.paddingX':'space.16','panel.paddingY':'space.20',
  'compact.background':'semantic.surface.subtle','compact.radius':'radius.4xl','compact.padding':'space.16','compact.height':'size.38',
  'growth.background':'semantic.surface.subtle','growth.radius':'radius.xl','growth.plotRadius':'radius.11','growth.expense':'color.blue.400','growth.revenue':'color.red.400','growth.customers':'color.amber.400','growth.height':'size.196',
  'request.duration':'motion.duration.chatRequest','result.duration':'motion.duration.enter','column.duration':'motion.duration.normal','reorder.duration':'motion.duration.chatReorder','enter.easing':'motion.easing.standard','reorder.easing':'motion.easing.chatReorder'
 };
 for(const [key,target]of Object.entries(roles))F.addToken('component.sourceChat.'+key,F.tokens[target].type,`{${target}}`,'normalized');
 const keys=prefix=>Object.keys(roles).filter(key=>!prefix||key.startsWith(prefix+'.')).map(key=>'component.sourceChat.'+key);
 const core=['font.family.sans','font.weight.400','font.weight.500','font.size.11','font.size.12','font.size.14','font.size.16','font.size.24','font.line.16','font.line.18','font.line.20','font.line.24','font.line.32','semantic.text.heading','semantic.text.placeholder','semantic.surface.canvas','semantic.surface.subtle','semantic.text.link','space.2','space.4','space.6','space.8','space.12','space.12','size.14','space.16','space.20','space.20','space.24','space.28','space.32','space.36','space.48','space.64','radius.sm','radius.md','radius.lg','border.width','shadow.focus','shadow.modal','layer.dropdown','layer.modal'];
