  const close=(restore=false)=>{const pop=active,button=origin;active=null;origin=null;if(pop){if(pop.matches?.(':popover-open'))pop.hidePopover?.();pop.hidden=true;}button?.setAttribute('aria-expanded','false');if(restore&&button?.isConnected)button.focus();};
  const position=()=>{if(!active||!origin)return;const r=origin.getBoundingClientRect(),w=active.offsetWidth||320,h=active.offsetHeight||200,vw=view.innerWidth||1024,vh=view.innerHeight||768;active.style.left=Math.max(8,Math.min(vw-w-8,r.left))+'px';active.style.top=Math.max(8,Math.min(vh-h-8,r.bottom+8))+'px';};
  const open=(pop,trigger)=>{if(!pop)return;close();active=pop;origin=trigger;pop.hidden=false;pop.showPopover?.();trigger?.setAttribute('aria-expanded','true');position();pop.querySelector('input,button')?.focus();};
  chatHosts(root).forEach(host=>{
   host.querySelectorAll('[data-chat-popup-trigger]').forEach(trigger=>listen(trigger,'click',()=>{const pop=host.querySelector('#'+trigger.getAttribute('aria-controls'));if(active===pop)close(true);else open(pop,trigger);}));
   host.querySelectorAll('[data-chat-popup]').forEach(pop=>listen(pop,'toggle',event=>{if(event.newState==='closed'&&active===pop)close(false);}));
   host.querySelectorAll('[data-chat-history-popup]').forEach(pop=>{
    const input=pop.querySelector('[data-chat-history-search]'),results=pop.querySelector('[data-chat-history-results]'),data=JSON.parse(pop.querySelector('[data-chat-history-data]').textContent);
    listen(input,'input',()=>{results.innerHTML=historyRows(data,input.value);position();});
    listen(results,'click',event=>{const button=event.target.closest('[data-chat-history-select]');if(!button)return;const item=data.find(item=>item.id===button.dataset.chatHistorySelect);if(!item)return;const title=host.querySelector('[data-chat-current-title]');if(title)title.textContent=item.title;announce(host,'Selected conversation: '+item.title);host.dispatchEvent(new CustomEvent('forma:conversation-select',{bubbles:true,detail:{id:item.id,title:item.title}}));close(true);});
   });
   host.querySelectorAll('[data-chat-save]').forEach(save=>{
    const pop=save.querySelector('[data-chat-popup]'),choices=save.querySelector('[data-chat-save-choices]'),membership=save.querySelector('[data-chat-save-membership]'),dialog=save.querySelector('[data-chat-save-dialog]');
    listen(save,'click',event=>{const button=event.target.closest('[data-chat-save-kind]');if(button&&!button.disabled){if(button.dataset.chatSaveKind==='existing'){choices.hidden=true;membership.hidden=false;position();membership.querySelector('input,button')?.focus();}else{const kind=button.dataset.chatSaveKind;close();dialog.querySelectorAll('[data-chat-save-form]').forEach(form=>form.hidden=form.dataset.chatSaveForm!==kind);if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');dialog.querySelector('[data-chat-save-form]:not([hidden]) input')?.focus();}}});
    listen(save.querySelector('[data-chat-save-back]'),'click',()=>{membership.hidden=true;choices.hidden=false;position();choices.querySelector('button:not(:disabled)')?.focus();});
    listen(save.querySelector('[data-chat-dialog-close]'),'click',()=>dialog.close?.());
    listen(dialog,'close',()=>{save.querySelector('[data-chat-popup-trigger]')?.focus();});
    listen(dialog,'forma:collection-save',event=>{announce(host,`List “${event.detail.name}” saved in this local example.`);dialog.close?.();});
    cleanup.push(()=>{if(dialog.open)dialog.close?.();});
   });
   const animations=new Set(),reduced=view.matchMedia?.('(prefers-reduced-motion: reduce)'),canvas=host.closest?.('.pp-theme');
   const paused=()=>!!doc.body?.classList?.contains('motion-paused')||!!canvas?.classList?.contains('preview-paused');
   const stopMotion=()=>{animations.forEach(animation=>{animation.finish?.();animation.cancel?.();});animations.clear();};
   const move=(node,frames,duration,easing)=>{if(!node.animate||reduced?.matches||paused())return;const speed=Number.parseFloat(view.getComputedStyle?.(host).getPropertyValue('--speed'))||1;const animation=node.animate(frames,{duration:duration/Math.max(.1,speed),easing});animations.add(animation);animation.onfinish=()=>animations.delete(animation);};
   listen(host,'forma:table-change',event=>{if(reduced?.matches||paused())return;const table=event.target;table.querySelectorAll('[data-previous-index]').forEach(row=>{const before=Number(row.dataset.previousIndex),after=Number(row.dataset.currentIndex);if(before<0){move(row,[{opacity:0},{opacity:1}],200,F.resolve('component.sourceChat.enter.easing'));return;}if(before===after)return;const distance=Math.max(-120,Math.min(120,(before-after)*row.getBoundingClientRect().height));move(row,[{transform:`translateY(${distance}px)`,opacity:.45},{transform:'translateY(0)',opacity:1}],240,F.resolve('component.sourceChat.reorder.easing'));});});
   listen(reduced,'change',()=>{if(reduced.matches)stopMotion();});
   if(view.MutationObserver){const observer=new view.MutationObserver(()=>{if(paused())stopMotion();});if(doc.body)observer.observe(doc.body,{attributes:true,attributeFilter:['class']});if(canvas)observer.observe(canvas,{attributes:true,attributeFilter:['class']});cleanup.push(()=>observer.disconnect());}
   cleanup.push(stopMotion);
   listen(host,'forma:save-list',event=>{const surface=host.querySelector('.pp-chat-result-save'),trigger=surface?.querySelector('[data-chat-popup-trigger]'),pop=surface?.querySelector('[data-chat-popup]');if(!surface)return;event.preventDefault();surface.hidden=false;open(pop,event.target.querySelector?.('[data-chat-save-list]')||trigger);});
   const panel=host.querySelector('[data-chat-panel]'),opener=host.querySelector('[data-chat-panel-open]');
   listen(host.querySelector('[data-chat-panel-close]'),'click',()=>{panel.hidden=true;opener.hidden=false;opener.focus();});
   listen(opener,'click',()=>{panel.hidden=false;opener.hidden=true;panel.querySelector('textarea')?.focus();});
   const compose=host.querySelector('[data-chat-compact-compose]'),textarea=compose?.querySelector('textarea'),file=compose?.querySelector('[data-chat-file]');
   listen(compose?.querySelector('[data-chat-attach]'),'click',()=>file.click());
   listen(file,'change',()=>{compose.querySelector('[data-chat-file-name]').textContent=file.files?.[0]?.name||'';});
   const send=()=>{if(!textarea||textarea.disabled)return;if(!textarea.value.trim()){textarea.setCustomValidity?.('Enter a question.');textarea.reportValidity?.();return;}textarea.setCustomValidity?.('');const text=textarea.value.trim(),filename=file.files?.[0]?.name;host.querySelector('[data-chat-messages]').insertAdjacentHTML('beforeend',F.chatMessage({text,files:filename?[filename]:[]}));textarea.value='';file.value='';compose.querySelector('[data-chat-file-name]').textContent='';announce(host,'Message added locally. No AI service is connected.');host.dispatchEvent(new CustomEvent('forma:conversation-send',{bubbles:true,detail:{text}}));textarea.focus();};
   listen(compose,'submit',event=>{event.preventDefault();send();});listen(textarea,'input',()=>textarea.setCustomValidity?.(''));
   listen(textarea,'keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();send();}});
   listen(host,'click',event=>{const link=event.target.closest('[data-chat-new]');if(!link)return;event.preventDefault();announce(host,'New conversation selected.');host.dispatchEvent(new CustomEvent('forma:conversation-new',{bubbles:true}));});
  });
